  public enum TableAction {
    /// <summary>
    /// 테이블 액션 없음													
    /// </summary>
    [pbr::OriginalName("TableAction_None")] None = 0,
    /// <summary>
    /// 이전 참여 금액을 맞추는 액션										// 콜 : 앞사람의 베팅 금액과 동일한 금액 베팅 (CALL)
    /// </summary>
    [pbr::OriginalName("TableAction_Call")] Call = 101,
    /// <summary>
    /// 기본 판돈만 참여하는 액션									// 삥 : 시드금액(기본판돈)만 베팅 (보스만 가능), 교환 간 1회만 가능함
    /// </summary>
    [pbr::OriginalName("TableAction_SeedOnly")] SeedOnly = 102,
    /// <summary>
    /// 이전 참여 금액의 두 배 액션								// 따당 : 앞 사람이 베팅한 금액의 2배를 베팅함 (CALL*2)
    /// </summary>
    [pbr::OriginalName("TableAction_DoubleRaise")] DoubleRaise = 103,
    /// <summary>
    /// 전체 판돈의 50퍼센트 기준 액션								// 하프 : 전체 판돈의 50%를 베팅, (POT+CALL)*1/2+CALL
    /// </summary>
    [pbr::OriginalName("TableAction_HalfPot")] HalfPot = 104,
    /// <summary>
    /// 진행 포기 액션													// 다이 : 해당 게임을 포기함
    /// </summary>
    [pbr::OriginalName("TableAction_GiveUp")] GiveUp = 105,
    /// <summary>
    /// 금액 추가 없이 순서를 넘기는 액션								// 체크 : 베팅하지 않고, 다음 플레이어 베팅 순으로 넘김(0)
    /// </summary>
    [pbr::OriginalName("TableAction_Check")] Check = 106,
    /// <summary>
    /// 전체 판돈의 25퍼센트 기준 액션								// 전체 판돈의 25%를 베팅, (POT+CALL)*(1/4)+CALL
    /// </summary>
    [pbr::OriginalName("TableAction_QuarterPot")] QuarterPot = 107,
    /// <summary>
    /// 허용 범위 내 최대 액션									    // 맥스 : 플레이어의 베팅 한도 내 최대 베팅
    /// </summary>
    [pbr::OriginalName("TableAction_Maximum")] Maximum = 108,
    /// <summary>
    /// 홀덤 스몰 블라인드 액션									// 홀덤 : SB
    /// </summary>
    [pbr::OriginalName("TableAction_SmallBlind")] SmallBlind = 201,
    /// <summary>
    /// 홀덤 빅 블라인드 액션										// 홀덤 : BB
    /// </summary>
    [pbr::OriginalName("TableAction_BigBlind")] BigBlind = 202,
    /// <summary>
